<?php
namespace App\Http\Controllers;
use App\Models\RolePermission;use App\Services\AuditLogService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\DB;
class RolePermissionController extends Controller { private const ROLES=['admin','seller','seller_staff','reseller']; public function index():JsonResponse{return response()->json($this->rows());} public function save(Request $request,AuditLogService $audit):JsonResponse{$data=$request->validate(['roles'=>['required','array','size:4'],'roles.*.id'=>['required','in:admin,seller,seller_staff,reseller','distinct'],'roles.*.permissions'=>['present','array']]);$by=collect($data['roles'])->keyBy('id');DB::transaction(function()use($by,$request){foreach(self::ROLES as $role){$permissions=$this->sanitize($role,$by[$role]['permissions']??[]);RolePermission::updateOrCreate(['role'=>$role],['permissions'=>$permissions,'updated_by'=>$request->user()->id]);Cache::forget("rbac.$role");}});$audit->record($request,'admins.manage','roles.updated',null,['roles'=>$this->rows()]);$request->attributes->set('rbac_audited',true);return response()->json($this->rows());} private function rows():array{return collect(self::ROLES)->map(fn($role)=>['id'=>$role,'permissions'=>RolePermission::where('role',$role)->value('permissions')??config("rbac.defaults.$role",[])])->all();} private function sanitize(string $role,array $permissions):array{$allowed=config("rbac.permissions");$result=array_values(array_unique(array_filter($permissions,fn($p)=>is_string($p)&&array_key_exists($p,$allowed)&&in_array($role,$allowed[$p],true))));if($role==='seller_staff')$result=array_values(array_filter($result,fn($p)=>!str_ends_with($p,'.delete')&&!in_array($p,['store.profile','staff.manage'],true)));return $role==='reseller'?array_values(array_intersect($result,config('rbac.defaults.reseller'))):$result;} }
